package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen4Test {



    @Test
    public void testToBoolean_TrueCases() {
        // Test interned "true" (covers the str == "true" branch)
        assertTrue(BooleanUtils.toBoolean("true"));

        // Test non-interned "true" (covers case 4, lowercase 't')
        assertTrue(BooleanUtils.toBoolean(new String("true")));

        // Test uppercase "TRUE" (covers case 4, uppercase 'T')
        assertTrue(BooleanUtils.toBoolean("TRUE"));

        // Test mixed case "tRuE" (covers case 4, lowercase 't')
        assertTrue(BooleanUtils.toBoolean("tRuE"));

        // Test mixed case "TrUe" (covers case 4, uppercase 'T')
        assertTrue(BooleanUtils.toBoolean("TrUe"));

        // Test mixed case "tREu" (covers case 4, lowercase 't')
        assertTrue(BooleanUtils.toBoolean("tREu"));

        // Test mixed case "TRue" (covers case 4, uppercase 'T')
        assertTrue(BooleanUtils.toBoolean("TRue"));
    }










}

package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen4Test {





    @Test
    public void testToBoolean_OnCases() {
        // Case 2: 'o' or 'O' and 'n' or 'N'
        assertTrue(BooleanUtils.toBoolean("on"));
        assertTrue(BooleanUtils.toBoolean("ON"));
        assertTrue(BooleanUtils.toBoolean("oN"));
        assertTrue(BooleanUtils.toBoolean("On"));

        // Negative cases for length 2
        assertFalse(BooleanUtils.toBoolean("ox"));
        assertFalse(BooleanUtils.toBoolean("an"));
        assertFalse(BooleanUtils.toBoolean("o"));
        assertFalse(BooleanUtils.toBoolean("onn"));
    }








}

package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen4Test {







    @Test
    public void testToBoolean_YesCases() {
        // Case 3: 'y' or 'Y' and 'e' or 'E' and 's' or 'S'
        assertTrue(BooleanUtils.toBoolean("yes"));
        assertTrue(BooleanUtils.toBoolean("YES"));
        assertTrue(BooleanUtils.toBoolean("yEs"));
        assertTrue(BooleanUtils.toBoolean("YeS"));
        assertTrue(BooleanUtils.toBoolean("YEs"));
        assertTrue(BooleanUtils.toBoolean("yES"));
        assertTrue(BooleanUtils.toBoolean("YeS"));
        assertTrue(BooleanUtils.toBoolean("yEs"));

        // Specific branch coverage for 'y' vs 'Y'
        assertTrue(BooleanUtils.toBoolean("yEs"));
        assertTrue(BooleanUtils.toBoolean("YEs"));

        // Negative cases for length 3
        assertFalse(BooleanUtils.toBoolean("yex"));
        assertFalse(BooleanUtils.toBoolean("yen"));
        assertFalse(BooleanUtils.toBoolean("yesx"));
        assertFalse(BooleanUtils.toBoolean("abc"));
    }






}

