package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class BooleanUtils_toBoolean_TriageGen4Test {













    @Test
    public void testToBoolean_BranchCoverageSpecifics() {
        // Test case 4 't' branch with various combinations
        assertTrue(BooleanUtils.toBoolean("tRuE"));
        assertTrue(BooleanUtils.toBoolean("tRUE"));
        assertTrue(BooleanUtils.toBoolean("trUE"));
        assertTrue(BooleanUtils.toBoolean("truE"));

        // Test case 4 'T' branch with various combinations
        assertTrue(BooleanUtils.toBoolean("TRue"));
        assertTrue(BooleanUtils.toBoolean("TrUE"));
        assertTrue(BooleanUtils.toBoolean("TrUe"));
        assertTrue(BooleanUtils.toBoolean("TReU")); // Wait, checking logic: (ch1=='R'||'r') && (ch2=='U'||'u') && (ch3=='E'||'e')
        assertTrue(BooleanUtils.toBoolean("TRuE"));

        // Test case 3 'y' branch specifics
        assertTrue(BooleanUtils.toBoolean("yEs"));
        assertTrue(BooleanUtils.toBoolean("yES"));
        assertTrue(BooleanUtils.toBoolean("yeS"));
        assertTrue(BooleanUtils.toBoolean("yEs"));

        // Test case 3 'Y' branch specifics
        assertTrue(BooleanUtils.toBoolean("YEs"));
        assertTrue(BooleanUtils.toBoolean("YeS"));
        assertTrue(BooleanUtils.toBoolean("YES"));
        assertTrue(BooleanUtils.toBoolean("YeS"));
    }
}
